package com.restro.restaurantservice.web.controller;
import com.restro.restaurantservice.service.HolidayService; import com.restro.restaurantservice.web.dto.HolidayRequest; import com.restro.restaurantservice.web.dto.HolidayResponse; import jakarta.validation.Valid; import java.time.LocalDate; import java.util.List; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/attendance/holidays") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class HolidayController { private final HolidayService service; public HolidayController(HolidayService service){this.service=service;} @GetMapping public List<HolidayResponse> list(@RequestParam(name="from") @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(name="to") @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.list(from,to);}@PostMapping public HolidayResponse create(@Valid @RequestBody HolidayRequest request){return service.create(request);}@PutMapping("/{id}") public HolidayResponse update(@PathVariable("id") Long id,@Valid @RequestBody HolidayRequest request){return service.update(id,request);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('OWNER')") public void delete(@PathVariable("id") Long id){service.delete(id);} }
